-- =====================================================================
--  G-SMaRT Integrated Accounting and Government Contracting System
--  Migration 2026_11_24: the estimates and targets of the transaction form,
--  the omnibus sworn statement and the bid securing declaration
--
--  Run it ONCE on every company database, after a backup (phpMyAdmin: select
--  the database > Import; Navicat: Execute SQL File; or the mysql command).
--  It needs 2026_11_23_customer_zip_treasurer.sql (version 35) to have been run first.
--  Written for MySQL 5.5.3+ and MariaDB 5.5+. Safe to run more than once.
--  New installs do not need it (database/schema.sql includes everything).
--
--  What it changes
--    1. One empty column on brgy_projects:
--         est_sop_rate   the SOP of the transaction form as a % of the gross amount
--                        (blank: the SOP is the amount in est_sop, as before)
--       No accounting entry is made from the estimates.
--    2. The template "Omnibus sworn statement (prescribed form)" becomes the whole
--       omnibus sworn statement, like the other forms: its text, its header (the title
--       over a rule), its footer and its affiant are changed on the template.
--    3. The template "Bid securing declaration (prescribed form)" becomes the whole bid
--       securing declaration in the same way.
--       Both are no longer marked as prescribed shells. The version before stays under
--       Proforma & Form Templates > the template > Versions ("Put back" restores it).
--
--  Nothing is deleted and no amount or posting changes. Forms already prepared keep
--  their text; a draft takes the new text with "Fill again from the records".
-- =====================================================================

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
--  1. The SOP as a % of the gross amount
-- ---------------------------------------------------------------------
SET @sql = (SELECT IF(COUNT(*) = 0,
  'ALTER TABLE brgy_projects ADD COLUMN est_sop_rate DECIMAL(5,2) NULL AFTER est_sop',
  'SELECT ''brgy_projects: est_sop_rate already exists''')
  FROM information_schema.columns
 WHERE table_schema = DATABASE() AND table_name = 'brgy_projects' AND column_name = 'est_sop_rate');
PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;

-- ---------------------------------------------------------------------
--  2. and 3. The omnibus sworn statement and the bid securing declaration
-- ---------------------------------------------------------------------
SET @oss_name = 'Omnibus sworn statement';
SET @oss_desc = 'The bidder\'s omnibus sworn statement (RA 12009 IRR), for notarization, filled from Contracting Settings and the transaction. The text is changed with Edit text; the header, footer and affiant on the Format tab.';
SET @oss_body = '<div>{{letterhead}}</div><div data-section="venue" title="Venue (Republic of the Philippines, S.S.)"><table class="fx-plain" style="width:auto;margin:0 0 6px"><tbody><tr><td style="padding:0 8px 0 0;white-space:nowrap">REPUBLIC OF THE PHILIPPINES</td><td style="padding:0 8px 0 0;white-space:nowrap">)</td><td></td></tr><tr><td style="padding:0 8px 0 0;white-space:nowrap">CITY/MUNICIPALITY OF ____________________</td><td style="padding:0 8px 0 0;white-space:nowrap">)</td><td>S.S.</td></tr></tbody></table></div><p style="text-align:center;margin:18px 0 16px;letter-spacing:.16em"><b>OMNIBUS SWORN STATEMENT</b></p><p style="text-align:justify;text-indent:2.5em">I, <b>{{signatory.name}}</b>, of legal age, {{signatory.civil_status}}, {{signatory.citizenship}}, and with residence at {{signatory.residence}}, after having been duly sworn in accordance with law, do hereby depose and state that:</p><ol style="text-align:justify;padding-left:2.4em;margin:10px 0 0"><li style="margin-bottom:8px">I am the sole proprietor or authorized representative of <b>{{company.bidder_upper}}</b> with office address at {{company.address}};</li><li style="margin-bottom:8px">As the owner and sole proprietor or authorized representative of <b>{{company.bidder_upper}}</b>, I have full power and authority to do, execute and perform any and all acts necessary or appoint {{project.submitter}} to represent my company for the bidding of the <b>{{project.title}}</b> at {{entity.title}}, {{entity.city}}, {{entity.province}};</li><li style="margin-bottom:8px"><b>{{company.bidder_upper}}</b> is not “blacklisted” or barred from bidding by the Government of the Philippines or any of its agencies, offices, corporations, or Local Government Units, foreign government/foreign or international financing institution whose blacklisting rules have been recognized by the Government Procurement Policy Board; by itself or by relation, membership, association, affiliation, or controlling interest with another blacklisted person or entity;</li><li style="margin-bottom:8px">Each of the documents submitted in satisfaction of the bidding requirements is an authentic copy of the original, complete, and all statements and information provided therein are true and correct;</li><li style="margin-bottom:8px"><b>{{company.bidder_upper}}</b> is authorizing the Head of the Procuring Entity or its duly authorized representative(s) to verify all the documents submitted;</li><li style="margin-bottom:8px">I am not related to the Head of the Procuring Entity, members of the Bids and Awards Committee (BAC), the Technical Working Group, and the BAC Secretariat, the head of the Project Management Office or the end-user unit, and the project consultants by consanguinity or affinity up to the third civil degree;</li><li style="margin-bottom:8px">It is understood that failure to faithfully disclose its relationship with the Head of the Procuring Entity, members of the BAC, the TWG, and the BAC Secretariat, the head of the PMO or the end-user unit or implementing unit, and the project consultants of the Procuring Entity, or of the procurement agent by consanguinity or affinity up to the third civil degree, as well as its submission of beneficial ownership information containing false entries shall be subject to blacklisting under Section 100 of the Implementing Rules and Regulations (IRR) of Republic Act (RA) No. 12009, without prejudice to criminal and civil liabilities under applicable laws, including their accessory penalties, if any;</li><li style="margin-bottom:8px"><b>{{company.bidder_upper}}</b> complies with existing labor laws and standards; and</li><li style="margin-bottom:8px"><b>{{company.bidder_upper}}</b> is aware of and has undertaken the following responsibilities as a Bidder:<div style="margin-top:6px"><p style="margin:0 0 6px 2.2em;text-indent:-1.8em;text-align:justify"><span style="display:inline-block;width:1.8em;text-indent:0">a)</span>Carefully examine all of the Bidding Documents;</p><p style="margin:0 0 6px 2.2em;text-indent:-1.8em;text-align:justify"><span style="display:inline-block;width:1.8em;text-indent:0">b)</span>Acknowledge all conditions, local or otherwise, affecting the implementation of the Contract;</p><p style="margin:0 0 6px 2.2em;text-indent:-1.8em;text-align:justify"><span style="display:inline-block;width:1.8em;text-indent:0">c)</span>Made an estimate of the facilities available and needed for the contract to be bid, if any; and</p><p style="margin:0 0 6px 2.2em;text-indent:-1.8em;text-align:justify"><span style="display:inline-block;width:1.8em;text-indent:0">d)</span>Inquire or secure Supplemental Bid Bulletin(s) issued for the <b>{{project.title}}</b>.</p></div></li><li style="margin-bottom:8px"><b>{{company.bidder_upper}}</b> did not give or pay directly or indirectly, any commission, amount, fee, or any form of consideration, pecuniary or otherwise, to any person or official, personnel or representative of the government in relation to any procurement project or activity.</li><li style="margin-bottom:8px">In case advance payment was made or given to <b>{{company.bidder_upper}}</b>, failure to perform or deliver any of the obligations and undertakings in the contract shall be sufficient grounds to constitute criminal liability under existing laws.</li></ol><p style="text-align:justify;text-indent:2.5em;margin-top:14px">IN WITNESS WHEREOF, I have hereunto set my hand this _____ day of ______________, 20_____ at {{company.notary_place}}, Philippines.</p><div>{{signatories}}</div><div data-section="jurat" title="Jurat of the notary public"><p style="text-align:justify;margin-top:22px"><b>SUBSCRIBED AND SWORN</b> to before me this _____ day of ______________, 20_____ at <u>{{company.notary_place}}, Philippines</u>. Affiant/s is/are personally known to me and was/were identified by me through competent evidence of identity as defined in the 2004 Rules on Notarial Practice (A.M. No. 02-8-13-SC). Affiant/s exhibited to me his/her {{signatory.id_type}} photograph and signature appearing thereon, with <u>{{signatory.id_type}} No. {{signatory.id_no}}</u>.</p><p style="margin-top:16px">WITNESS MY HAND AND SEAL this _____ day of ______________, 20_____.</p><p style="margin-top:20px;line-height:1.55">Doc. No. __________<br>Page No. __________<br>Book No. __________<br>Series of {{date.year}}.</p></div>';
SET @oss_layout = '{"paper":"Legal","orientation":"portrait","margin_top":20,"margin_right":25.4,"margin_bottom":20,"margin_left":25.4,"font":"CG Omega","font_size":11,"line_height":1.3,"title_size":14,"table_size":10,"cell_pad":2,"date_style":"mdy","blank_rows":0,"nothing_follows":0,"lh_style":"own","lh_left":"none","lh_right":"none","lh_lines":"# Omnibus Sworn Statement","lh_align":"center","lh_font":"","lh_size":11,"lh_big":14,"lh_pic_mm":24,"lh_box":0,"lh_box_bg":"#ffffff","lh_box_fg":"#111111","lh_rule":1,"lh_rule_color":"#111111","lh_space":8,"lh_pic_a":"","lh_pic_b":"","footer":"","footer_align":"center","footer_bold":0,"footer_size":8,"footer_pos":"bottom","sig_cols":1,"sig_top":14,"sig_space":12,"sig_gap":8,"signatories":[{"lead":"","name":"{{signatory.name}}","pos":"Affiant","extra":"","align":"center","newrow":0,"line":0,"bold":1,"underline":0,"upper":0,"italic":0}]}';
SET @bsd_name = 'Bid securing declaration';
SET @bsd_desc = 'The bidder\'s bid securing declaration (RA 12009 IRR), for notarization, filled from Contracting Settings and the transaction. The text is changed with Edit text; the header, footer and affiant on the Format tab.';
SET @bsd_body = '<div>{{letterhead}}</div><div data-section="venue" title="Venue (Republic of the Philippines, S.S.)"><table class="fx-plain" style="width:auto;margin:0 0 6px"><tbody><tr><td style="padding:0 8px 0 0;white-space:nowrap">REPUBLIC OF THE PHILIPPINES</td><td style="padding:0 8px 0 0;white-space:nowrap">)</td><td></td></tr><tr><td style="padding:0 8px 0 0;white-space:nowrap">CITY/MUNICIPALITY OF ____________________</td><td style="padding:0 8px 0 0;white-space:nowrap">)</td><td>S.S.</td></tr></tbody></table></div><p style="text-align:center;margin:18px 0 2px"><b style="font-size:1.15em">BID SECURING DECLARATION</b></p><p style="text-align:center;margin:0 0 18px"><b>Project Identification No.: <u>{{project.reference_no}}</u></b></p><p style="margin:0 0 14px"><b><i>To: {{entity.title}}</i></b><br><b><i><span style="padding-left:2em">{{entity.location}}, {{entity.province}}</span></i></b></p><p>I/We, the undersigned, declare that:</p><ol style="text-align:justify;padding-left:2.4em;margin:10px 0 0"><li style="margin-bottom:8px">I/We understand that, according to your conditions, bids must be supported by a Bid Security, which may be in the form of a Bid Securing Declaration;</li><li style="margin-bottom:8px">I/We accept that: (a) I/we will be automatically disqualified from bidding for any procurement contract with any Procuring Entity upon receipt of your Blacklisting Order; and, (b) I/we will pay the applicable fine provided under the Guidelines on the Use of Bid Securing Declaration, within fifteen (15) days from receipt of the written demand by the Procuring Entity for the commission of acts resulting to the enforcement of the Bid Securing Declaration under Sections 52.2 (a), 63.2, 69.1 and 100, except 100.3 (c), of the IRR of Republic Act No. 12009; without prejudice to other legal action the government may undertake; and</li><li style="margin-bottom:8px">I/We understand that this Bid Securing Declaration shall cease to be valid on the following circumstances:<div style="margin-top:6px"><p style="margin:0 0 6px 2.2em;text-indent:-1.8em;text-align:justify"><span style="display:inline-block;width:1.8em;text-indent:0">a)</span>Upon expiration of the bid validity period, or any extension thereof pursuant to your request;</p><p style="margin:0 0 6px 2.2em;text-indent:-1.8em;text-align:justify"><span style="display:inline-block;width:1.8em;text-indent:0">b)</span>I am/we are declared ineligible or post-disqualified upon receipt of your notice to such effect, and (i) I/we failed to timely file a request for reconsideration or (ii) I/we filed a waiver to avail of said right;</p><p style="margin:0 0 6px 2.2em;text-indent:-1.8em;text-align:justify"><span style="display:inline-block;width:1.8em;text-indent:0">c)</span>Upon contract award and the LCCRB is not the original offeror; or</p><p style="margin:0 0 6px 2.2em;text-indent:-1.8em;text-align:justify"><span style="display:inline-block;width:1.8em;text-indent:0">d)</span>I am/we are declared the bidder with the Lowest Calculated and Responsive/Highest Rated and Responsive Bid and I/we have furnished the performance security and signed the Contract.</p></div></li></ol><p style="text-align:justify;text-indent:2.5em;margin-top:14px">IN WITNESS WHEREOF, I/We have hereunto set my/our hand/s this _____ day of ______________, 20_____ at {{company.notary_place}}, Philippines.</p><div>{{signatories}}</div><div data-section="jurat" title="Jurat of the notary public"><p style="text-align:justify;margin-top:22px"><b>SUBSCRIBED AND SWORN</b> to before me this _____ day of ______________, 20_____ at <u>{{company.notary_place}}, Philippines</u>. Affiant/s is/are personally known to me and was/were identified by me through competent evidence of identity as defined in the 2004 Rules on Notarial Practice (A.M. No. 02-8-13-SC). Affiant/s exhibited to me his/her  photograph and signature appearing thereon, with <u>{{signatory.id_type}} No. {{signatory.id_no}}</u>.</p><p style="margin-top:16px">WITNESS MY HAND AND SEAL this _____ day of ______________, 20_____.</p><p style="margin-top:20px;line-height:1.55">Doc. No. __________<br>Page No. __________<br>Book No. __________<br>Series of {{date.year}}.</p></div>';
SET @bsd_layout = '{"paper":"Legal","orientation":"portrait","margin_top":20,"margin_right":25.4,"margin_bottom":20,"margin_left":25.4,"font":"CG Omega","font_size":11,"line_height":1.3,"title_size":14,"table_size":10,"cell_pad":2,"date_style":"mdy","blank_rows":0,"nothing_follows":0,"lh_style":"own","lh_left":"none","lh_right":"none","lh_lines":"# Bid Securing Declaration\\n({{project.title}})","lh_align":"center","lh_font":"","lh_size":11,"lh_big":14,"lh_pic_mm":24,"lh_box":0,"lh_box_bg":"#ffffff","lh_box_fg":"#111111","lh_rule":1,"lh_rule_color":"#111111","lh_space":8,"lh_pic_a":"","lh_pic_b":"","footer":"","footer_align":"center","footer_bold":0,"footer_size":8,"footer_pos":"bottom","sig_cols":1,"sig_top":14,"sig_space":12,"sig_gap":8,"signatories":[{"lead":"","name":"{{signatory.name}}","pos":"Affiant","extra":"","align":"center","newrow":0,"line":0,"bold":1,"underline":0,"upper":0,"italic":0}]}';

-- the omnibus sworn statement: the version before is kept, then the whole form (only once)
INSERT INTO brgy_template_versions (template_id, version_no, name, body, layout_json, positions_json, change_note)
SELECT t.id, t.version_no, t.name, t.body, t.layout_json, t.positions_json, 'Kept before version 37'
  FROM brgy_templates t
 WHERE t.code = 'omnibus_sworn_statement' AND INSTR(t.body, '{{signatory.residence}}') = 0
   AND NOT EXISTS (SELECT 1 FROM brgy_template_versions v WHERE v.template_id = t.id AND v.version_no = t.version_no);

UPDATE brgy_templates SET name = @oss_name, category = 'proforma', description = @oss_desc, body = @oss_body, layout_json = @oss_layout, paper = 'Legal', orientation = 'portrait',
       is_prescribed = 0, official_source = NULL, official_version = NULL, version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'omnibus_sworn_statement' AND INSTR(body, '{{signatory.residence}}') = 0;

INSERT INTO brgy_template_versions (template_id, version_no, name, body, layout_json, positions_json, change_note)
SELECT t.id, t.version_no, t.name, t.body, t.layout_json, t.positions_json, 'Version 37: the whole omnibus sworn statement (text, header, footer and affiant changed on the template)'
  FROM brgy_templates t
 WHERE t.code = 'omnibus_sworn_statement' AND INSTR(t.body, '{{signatory.residence}}') > 0
   AND NOT EXISTS (SELECT 1 FROM brgy_template_versions v WHERE v.template_id = t.id AND v.version_no = t.version_no);

-- the bid securing declaration: the version before is kept, then the whole form (only once)
INSERT INTO brgy_template_versions (template_id, version_no, name, body, layout_json, positions_json, change_note)
SELECT t.id, t.version_no, t.name, t.body, t.layout_json, t.positions_json, 'Kept before version 37'
  FROM brgy_templates t
 WHERE t.code = 'bid_securing_declaration' AND INSTR(t.body, 'I/We, the undersigned, declare that') = 0
   AND NOT EXISTS (SELECT 1 FROM brgy_template_versions v WHERE v.template_id = t.id AND v.version_no = t.version_no);

UPDATE brgy_templates SET name = @bsd_name, category = 'proforma', description = @bsd_desc, body = @bsd_body, layout_json = @bsd_layout, paper = 'Legal', orientation = 'portrait',
       is_prescribed = 0, official_source = NULL, official_version = NULL, version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'bid_securing_declaration' AND INSTR(body, 'I/We, the undersigned, declare that') = 0;

INSERT INTO brgy_template_versions (template_id, version_no, name, body, layout_json, positions_json, change_note)
SELECT t.id, t.version_no, t.name, t.body, t.layout_json, t.positions_json, 'Version 37: the whole bid securing declaration (text, header, footer and affiant changed on the template)'
  FROM brgy_templates t
 WHERE t.code = 'bid_securing_declaration' AND INSTR(t.body, 'I/We, the undersigned, declare that') > 0
   AND NOT EXISTS (SELECT 1 FROM brgy_template_versions v WHERE v.template_id = t.id AND v.version_no = t.version_no);

